SELECT 
FROM dms_admin_user u LEFT JOIN dms_merchant m ON m.id=u.merchant_id


        AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR m.merchant_name LIKE CONCAT('%', #{keyword}, '%'))


        AND u.status = #{status}


        AND u.merchant_id = #{merchantId}


ORDER BY u.id DESC

SELECT 
FROM dms_admin_user u LEFT JOIN dms_merchant m ON m.id=u.merchant_id
WHERE u.id = #{id}

