UPDATE dms_admin_user
SET last_login_time = NOW(), failed_login_count = 0, lock_time = NULL, update_time = NOW()
WHERE id = #{id}

UPDATE dms_admin_user
SET failed_login_count=0, lock_time=NULL, update_time=NOW()
WHERE id=#{id} AND lock_time IS NOT NULL AND lock_time <= #{expiredBefore}
